DROP TABLE IF EXISTS `Client_List`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Client_List` (
  `Client_Unique_ID` int NOT NULL AUTO_INCREMENT,
  `Client_Name` varchar(100) NOT NULL,
  `Town` varchar(100) NOT NULL,
  `City` varchar(100) DEFAULT NULL,
  `Phone_Number` varchar(20) DEFAULT NULL,
  `Client_Code` varchar(50) DEFAULT NULL,
  `Contact_Person` varchar(100) DEFAULT NULL,
  `email_address` varchar(100) DEFAULT NULL,
  `Alias_Name` varchar(255) DEFAULT NULL,
  `Installer` varchar(255) DEFAULT 'Tino Team',
  `general_comment` text,
  PRIMARY KEY (`Client_Unique_ID`,`Client_Name`),
  UNIQUE KEY `unique_client` (`Client_Name`,`Town`,`City`,`Phone_Number`,`Client_Code`,`Contact_Person`,`email_address`)
) ENGINE=InnoDB AUTO_INCREMENT=2175 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
