--
-- Table structure for table `Job_Tracking`
--

DROP TABLE IF EXISTS `Job_Tracking`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Job_Tracking` (
  `Job_ID` int NOT NULL AUTO_INCREMENT,
  `Client_Unique_ID` int DEFAULT NULL,
  `Client_Name` varchar(255) DEFAULT NULL,
  `Town` varchar(255) DEFAULT NULL,
  `Phone_Number` varchar(20) DEFAULT NULL,
  `Date` date DEFAULT NULL,
  `Tasks_Performed` varchar(1000) DEFAULT NULL,
  `Any_Issues` varchar(1000) DEFAULT NULL,
  `Percentage_Completion` decimal(5,2) DEFAULT NULL,
  PRIMARY KEY (`Job_ID`),
  KEY `Client_Unique_ID` (`Client_Name`),
  KEY `job_tracking_fk_client_unique_id` (`Client_Unique_ID`),
  CONSTRAINT `job_tracking_fk_client_unique_id` FOREIGN KEY (`Client_Unique_ID`) REFERENCES `Client_List` (`Client_Unique_ID`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=813 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

