/*50003 CREATE*/ /*!50017 DEFINER=`ygj9awwzkwyiakxw`@`%`*/ /*!50003 TRIGGER `after_sales_insert` AFTER INSERT ON `sales_by_item` FOR EACH ROW BEGIN
    DECLARE item_component VARCHAR(255);
    DECLARE installer_name VARCHAR(255);

    -- Lookup the component from the Items_List table
    SELECT Component
    INTO item_component
    FROM Items_List
    WHERE Item_Description = NEW.item_description
    LIMIT 1;

    -- Assign a default value if no matching component is found
    IF item_component IS NULL THEN
        SET item_component = 'Unknown';
    END IF;

    -- Lookup the Installer from the Client_List table where Alias_Name matches NEW.customer
    SELECT Installer
    INTO installer_name
    FROM Client_List
    WHERE Alias_Name = NEW.customer
    LIMIT 1;

    -- Assign a default value if no matching Installer is found
    IF installer_name IS NULL THEN
        SET installer_name = 'Tino Team';
    END IF;

    -- Insert into client_items
    INSERT INTO client_items (
        item_description,
        date,
        component,
        client_name,
        quantity,
        installed_by
    )
    VALUES (
        NEW.item_description,
        NEW.date,
        item_component,
        NEW.customer,
        NEW.qty_sold,
        installer_name
    );
END */;;
